t.script:
//
(function () {
    "use strict";

    var el = function (id) { return document.getElementById(id); };

    // Conversation continuity is session_id-driven, the same
    // way Frappe's own agent-chat page works
    // (chat_message_handler.js keys every /agent/ask call on
    // session_manager.session_id) — the razyyn server's own
    // LangGraph checkpointer holds prior turns keyed by this
    // id, so the client never resends earlier turns itself.
    // An earlier version of this page rebuilt a plain-text
    // "User: ...\nAssistant: ..." transcript and sent that as
    // a `history` field on every call — the server's history
    // parser expects JSON (or nothing) and raised "Invalid
    // history format" on the very first turn already, since
    // even the empty-string default reached a code path that
    // does not special-case it the way the top-level
    // coerce_history() does. Session-id-only avoids the
    // question entirely.
    var sessions = [];       // [{id, title}], newest first, client-side only for now
    var activeSessionId = null;

    function newSessionId() {
        if (window.crypto && window.crypto.randomUUID) { return window.crypto.randomUUID(); }
        return "sess-" + Date.now() + "-" + Math.random().toString(16).slice(2);
    }

    // UI-string translation only — English + Arabic, same
    // two languages Frappe's own .agent-lang-selector offers
    // (agent_chat.js:684-685). This is a plain client-side
    // swap (no server round trip, no i18n framework), unlike
    // Frappe's version which sets the signed-in user's own
    // `language` field and reloads so its `__()` framework
    // re-renders everything server-side too. The agent's
    // OWN replies are untouched by this — an LLM answers in
    // whichever language the message was written in on its
    // own, with no signal needed from here.
    var I18N = {
        en: {
            newChat: "+ New Chat", send: "Send", login: "Login", signUp: "Sign Up",
            emailAddress: "Email Address", password: "Password", connect: "Connect",
            companyName: "Company Name", companyNamePlaceholder: "e.g. My Company Corp",
            createAccount: "Create Account", checkingConnection: "Checking connection…",
            notConnected: "Not connected", connected: "Connected:", disconnect: "Disconnect",
            inputPlaceholder: "Type your financial question…", newChatTitle: "New chat", you: "You",
        },
        ar: {
            newChat: "+ محادثة جديدة", send: "إرسال", login: "تسجيل الدخول", signUp: "إنشاء حساب",
            emailAddress: "البريد الإلكتروني", password: "كلمة المرور", connect: "اتصال",
            companyName: "اسم الشركة", companyNamePlaceholder: "مثال: شركتي",
            createAccount: "إنشاء الحساب", checkingConnection: "جارٍ التحقق من الاتصال…",
            notConnected: "غير متصل", connected: "متصل:", disconnect: "قطع الاتصال",
            inputPlaceholder: "اكتب سؤالك المالي…", newChatTitle: "محادثة جديدة", you: "أنت",
        },
        fr: {
            newChat: "+ Nouvelle discussion", send: "Envoyer", login: "Connexion", signUp: "S'inscrire",
            emailAddress: "Adresse e-mail", password: "Mot de passe", connect: "Se connecter",
            companyName: "Nom de l'entreprise", companyNamePlaceholder: "ex. Ma Société SARL",
            createAccount: "Créer un compte", checkingConnection: "Vérification de la connexion…",
            notConnected: "Non connecté", connected: "Connecté :", disconnect: "Déconnecter",
            inputPlaceholder: "Posez votre question financière…", newChatTitle: "Nouvelle discussion", you: "Vous",
        },
    };
    var currentLang = "en";

    function t(key) { return (I18N[currentLang] || I18N.en)[key] || key; }

    function translateUI() {
        document.querySelectorAll("[data-i18n]").forEach(function (node) {
            node.textContent = t(node.getAttribute("data-i18n"));
        });
        document.querySelectorAll("[data-i18n-placeholder]").forEach(function (node) {
            node.setAttribute("placeholder", t(node.getAttribute("data-i18n-placeholder")));
        });
        document.documentElement.setAttribute("dir", currentLang === "ar" ? "rtl" : "ltr");
        document.documentElement.setAttribute("lang", currentLang);
    }

    function setLanguage(lang) {
        currentLang = I18N[lang] ? lang : "en";
        try { window.localStorage.setItem("razyyn-chat-lang", currentLang); } catch (e) { /* private mode, ignore */ }
        el("razyyn-lang-select").value = currentLang;
        translateUI();
    }

    (function initLanguage() {
        var saved = "en";
        try { saved = window.localStorage.getItem("razyyn-chat-lang") || "en"; } catch (e) { /* ignore */ }
        setLanguage(saved);
    })();
    el("razyyn-lang-select").addEventListener("change", function (evt) { setLanguage(evt.target.value); });

    function csrf() {
        var meta = document.querySelector('meta[name="csrf_token"]');
        return meta ? meta.getAttribute('content') : null;
    }

    function postJson(url, body) {
        var token = csrf();
        var headers = { "Content-Type": "application/json" };
        if (token) { headers["X-CSRF-Token"] = token; }
        return fetch(url, {
            method: "POST",
            headers: headers,
            body: JSON.stringify(body || {}),
            credentials: "same-origin",
        }).then(function (res) {
            return res.json().then(function (data) {
                return { ok: res.ok, status: res.status, data: data };
            });
        });
    }

    function getJson(url) {
        return fetch(url, { credentials: "same-origin" }).then(function (res) {
            return res.json().then(function (data) {
                return { ok: res.ok, status: res.status, data: data };
            });
        });
    }

    function showAuthMessage(text, kind) {
        var box = el("razyyn-auth-msg");
        box.className = "razyyn-msg " + kind;
        box.textContent = text;
        box.style.display = "block";
    }

    function switchTab(tab) {
        var isLogin = tab === "login";
        el("razyyn-tab-login").className = isLogin ? "active" : "";
        el("razyyn-tab-signup").className = isLogin ? "" : "active";
        el("razyyn-login-form").style.display = isLogin ? "block" : "none";
        el("razyyn-signup-form").style.display = isLogin ? "none" : "block";
        el("razyyn-auth-msg").style.display = "none";
    }
    el("razyyn-tab-login").addEventListener("click", function () { switchTab("login"); });
    el("razyyn-tab-signup").addEventListener("click", function () { switchTab("signup"); });

    function enterChat(email) {
        el("razyyn-auth-card").style.display = "none";
        el("razyyn-layout").style.display = "flex";
        el("razyyn-status").innerHTML = t("connected") + " <b>" + email +
            "</b>  <button type=\"button\" id=\"razyyn-disconnect\">" + t("disconnect") + "</button>";
        el("razyyn-disconnect").addEventListener("click", function () {
            postJson("/razyyn/disconnect", {}).then(function () { window.location.reload(); });
        });
        startNewChat();
    }

    function renderSessionList() {
        var list = el("razyyn-chat-list");
        list.innerHTML = "";
        sessions.forEach(function (session) {
            var item = document.createElement("div");
            item.className = "razyyn-chat-item" + (session.id === activeSessionId ? " active" : "");
            item.textContent = session.title;
            item.addEventListener("click", function () { switchToSession(session.id); });
            list.appendChild(item);
        });
    }

    function switchToSession(sessionId) {
        // Client-side only for now: this page has no
        // transcript-read endpoint (the Frappe app's
        // equivalent is backed by its own "Agent Chats"
        // doctype — see razyyn-odoo-17's README "Known
        // gaps" for messaging parity being similarly
        // scoped down). Switching re-targets new turns at
        // that session_id; it does not replay old ones.
        activeSessionId = sessionId;
        el("razyyn-thread").innerHTML = "";
        renderSessionList();
    }

    function startNewChat() {
        activeSessionId = newSessionId();
        sessions.unshift({ id: activeSessionId, title: t("newChatTitle") });
        el("razyyn-thread").innerHTML = "";
        renderSessionList();
    }
    el("razyyn-new-chat").addEventListener("click", startNewChat);

    function checkStatus() {
        getJson("/razyyn/status").then(function (res) {
            var msg = res.data.message || {};
            if (msg.connected) {
                enterChat(msg.email);
            } else {
                el("razyyn-status").textContent = t("notConnected");
            }
        }).catch(function () {
            el("razyyn-status").textContent = t("notConnected");
        });
    }

    el("razyyn-login-form").addEventListener("submit", function (evt) {
        evt.preventDefault();
        var submitBtn = evt.target.querySelector("button[type=submit]");
        submitBtn.disabled = true;
        postJson("/razyyn/authenticate", {
            mode: "login",
            email: el("razyyn-login-email").value,
            password: el("razyyn-login-password").value,
        }).then(function (res) {
            submitBtn.disabled = false;
            if (res.ok) {
                enterChat(res.data.message.email);
            } else {
                showAuthMessage(res.data.error || "Login failed.", "error");
            }
        });
    });

    el("razyyn-signup-form").addEventListener("submit", function (evt) {
        evt.preventDefault();
        var submitBtn = evt.target.querySelector("button[type=submit]");
        submitBtn.disabled = true;
        postJson("/razyyn/authenticate", {
            mode: "signup",
            company_name: el("razyyn-signup-company").value,
            email: el("razyyn-signup-email").value,
            password: el("razyyn-signup-password").value,
        }).then(function (res) {
            submitBtn.disabled = false;
            if (res.ok) {
                enterChat(res.data.message.email);
            } else {
                showAuthMessage(res.data.error || "Sign up failed.", "error");
            }
        });
    });

    // marked.js renderer override: a ```chartjs fence becomes a
    // sized placeholder div instead of a <pre><code> block, the
    // same interception chat_ui_manager.js's Renderer.code does
    // (agent_chat.js:185-201). Runs once, as soon as marked has
    // finished loading — the three CDN <script> tags in
    // head_website are plain blocking scripts, so by the time
    // this file's own script runs they are already available;
    // no onload/polling dance needed the way Frappe's
    // dynamic-inject loader requires one.
    if (window.marked) {
        var renderer = new window.marked.Renderer();
        renderer.code = function (code, language) {
            var codeText = code, lang = language;
            if (code && typeof code === "object") { codeText = code.text; lang = code.lang; }
            if (lang === "chartjs") {
                return '<div class="razyyn-chartjs-container" data-processed="false" data-code="' +
                    encodeURIComponent(codeText.trim()) + '"></div>';
            }
            return "<pre><code>" + codeText + "</code></pre>";
        };
        window.marked.use({ renderer: renderer, breaks: true, gfm: true });
    }

    // Every agent reply passes through here before it is ever
    // handed to innerHTML — marked's output (and doubly so
    // anything an LLM wrote) can carry a <script> or an
    // onerror=, so nothing leaves this function unsanitized.
    // Falls back to escaped plain text if either library
    // failed to load (CDN blocked, offline) rather than ever
    // emitting raw unsanitized HTML.
    function parseMarkdown(text) {
        if (!text) { return ""; }
        if (window.marked && window.DOMPurify) {
            try {
                return window.DOMPurify.sanitize(window.marked.parse(text));
            } catch (err) {
                console.error("marked parsing error:", err);
            }
        }
        var div = document.createElement("div");
        div.textContent = text;
        return div.innerHTML;
    }

    // Chart.js palette + defaults, copied from
    // chat_ui_manager.js's render_chartjs_diagrams so a chart
    // born from the same agent response looks the same here.
    var CHART_PALETTE = ["#1e40af", "#3b82f6", "#f59e0b", "#8b5cf6", "#ec4899", "#ef4444", "#06b6d4", "#14b8a6"];
    var CHART_HOVER_PALETTE = ["#1c348a", "#2563eb", "#d97706", "#7c3aed", "#db2777", "#dc2626", "#0891b2", "#0d9488"];

    function renderChartjsDiagrams(container) {
        if (typeof Chart === "undefined") {
            // CDN script is still downloading/executing — the
            // element exists in the DOM already (marked already
            // ran), Chart.js just has not finished loading yet.
            setTimeout(function () { renderChartjsDiagrams(container); }, 100);
            return;
        }
        var nodes = container.querySelectorAll('.razyyn-chartjs-container[data-processed="false"]');
        nodes.forEach(function (node) {
            node.setAttribute("data-processed", "true");
            var raw = decodeURIComponent(node.getAttribute("data-code") || "{}")
                .trim().replace(/,\s*([\]}])/g, "$1"); // trailing commas an LLM sometimes leaves in
            try {
                var config = JSON.parse(raw);
                if (!config.type) { config.type = "bar"; }
                if (!config.data) { config.data = { labels: [], datasets: [] }; }
                if (!config.data.datasets) { config.data.datasets = []; }

                config.data.datasets.forEach(function (dataset, idx) {
                    if (["pie", "doughnut", "polarArea"].indexOf(config.type) !== -1) {
                        var n = dataset.data ? dataset.data.length : 0;
                        dataset.backgroundColor = CHART_PALETTE.slice(0, n);
                        dataset.hoverBackgroundColor = CHART_HOVER_PALETTE.slice(0, n);
                        dataset.borderColor = "#ffffff";
                        dataset.borderWidth = 2;
                    } else {
                        var color = CHART_PALETTE[idx % CHART_PALETTE.length];
                        dataset.backgroundColor = color;
                        dataset.borderColor = color;
                        if (["line", "radar"].indexOf(config.type) !== -1) {
                            dataset.fill = dataset.fill || false;
                            dataset.tension = 0.3;
                        } else if (config.type === "bar") {
                            dataset.hoverBackgroundColor = CHART_HOVER_PALETTE[idx % CHART_HOVER_PALETTE.length];
                            dataset.borderRadius = 4;
                        }
                    }
                });

                config.options = Object.assign({
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: true, position: "bottom" } },
                }, config.options || {});

                node.innerHTML = "";
                var canvas = document.createElement("canvas");
                node.appendChild(canvas);
                new Chart(canvas, config);
            } catch (err) {
                console.error("Chart.js render error:", err);
                node.textContent = "Could not render this chart: " + (err.message || err);
            }
        });
    }

    function addBubble(who, text, kind) {
        var thread = el("razyyn-thread");
        var bubble = document.createElement("div");
        bubble.className = "razyyn-bubble " + kind;
        var whoLine = document.createElement("div");
        whoLine.className = "who";
        whoLine.textContent = who;
        var body = document.createElement("div");
        body.className = "body";
        body.textContent = text;
        bubble.appendChild(whoLine);
        bubble.appendChild(body);
        thread.appendChild(bubble);
        thread.scrollTop = thread.scrollHeight;
        return body;
    }

    function sendMessage() {
        var input = el("razyyn-input");
        var text = input.value.trim();
        if (!text) { return; }
        if (!activeSessionId) { startNewChat(); }
        input.value = "";
        addBubble(t("you"), text, "user");

        // First turn in a new chat: give the sidebar entry a
        // real title, the same moment Frappe's own session
        // manager renames a fresh session from its first
        // message.
        var session = sessions.filter(function (s) { return s.id === activeSessionId; })[0];
        if (session && session.title === t("newChatTitle")) {
            session.title = text.length > 40 ? text.slice(0, 40) + "…" : text;
            renderSessionList();
        }

        var sendBtn = el("razyyn-send");
        sendBtn.disabled = true;
        var thinking = addBubble("Razyyn", "Thinking…", "agent");

        postJson("/razyyn/ask", {
            message: text,
            session_id: activeSessionId,
        }).then(function (res) {
            sendBtn.disabled = false;
            if (res.ok) {
                var answer = (res.data.message && res.data.message.response) || "(no response)";
                thinking.innerHTML = parseMarkdown(answer);
                thinking.parentNode.className = "razyyn-bubble agent";
                renderChartjsDiagrams(thinking);
                el("razyyn-thread").scrollTop = el("razyyn-thread").scrollHeight;
            } else {
                thinking.textContent = res.data.error || "Something went wrong.";
                thinking.parentNode.className = "razyyn-bubble error";
            }
        }).catch(function () {
            sendBtn.disabled = false;
            thinking.textContent = "Could not reach the server.";
            thinking.parentNode.className = "razyyn-bubble error";
        });
    }

    el("razyyn-send").addEventListener("click", sendMessage);
    el("razyyn-input").addEventListener("keydown", function (evt) {
        if (evt.key === "Enter" && !evt.shiftKey) {
            evt.preventDefault();
            sendMessage();
        }
    });

    checkStatus();
})();
//
